INSERT INTO fault_code_dictionary (company_id, equipment_class, manufacturer, code, description_en, description_es, severity, likely_causes, recommended_action, source, created_at, updated_at) VALUES (NULL, 'CNC_MACHINING_CENTER_VMC', 'Haas Automation', '121', 'LOW LUBE OR LOW PRESSURE - the axis lubrication reservoir is low or empty, or the system is not developing pressure.', 'LUBRICACION BAJA O PRESION BAJA - el deposito de lubricacion de ejes esta bajo o vacio, o el sistema no genera presion.', 'HIGH', 'Empty way-lube reservoir; blocked or crushed lube line; failed metering unit; failed pressure switch; wrong oil viscosity clogging the system.', 'Do not keep running the machine. Check the reservoir level, then verify FLOW at each lubrication point during a pump cycle - the reservoir being full tells you nothing about whether oil is arriving. The Bijur pump delivers roughly 3 ml at about 35 psi every 30 minutes.', 'SEEDED', now(), now()),
(NULL, 'CNC_MACHINING_CENTER_VMC', 'Haas Automation', '102', 'SERVOS OFF - the servo motors are off; the tool changer, coolant pump and spindle are stopped.', 'SERVOS APAGADOS - los servomotores estan apagados; el cambiador, la bomba de refrigerante y el husillo estan detenidos.', 'MEDIUM', 'Emergency stop pressed; a companion alarm turned the servos off; low air pressure; overvoltage or undervoltage; door interlock.', 'Read the alarm history for the alarm that came first - 102 is usually the consequence, not the cause.', 'SEEDED', now(), now()),
(NULL, 'CNC_MACHINING_CENTER_VMC', 'Haas Automation', '119', 'OVERVOLTAGE - incoming line voltage is above maximum. Servos off; spindle, tool changer and coolant pump stop.', 'SOBRETENSION - la tension de entrada supera el maximo.', 'HIGH', 'Supply voltage high; transformer tap set wrong; regen resistor circuit fault.', 'Measure the incoming line voltage under load and check the transformer tap setting before restarting.', 'SEEDED', now(), now());
